export const { min, max, abs, floor } = Math;

/**
 * Behaves the same as clamp() in CSS: minValue wins if it's greater than maxValue.
 * https://drafts.csswg.org/css-values-4/#comp-func
 * @internal
 */
export const clamp = (
  value: number,
  minValue: number,
  maxValue: number,
): number => max(minValue, min(maxValue, value));

/**
